    function scGetColumnOrderRule($fieldName)
    {
        $sortRule = 'nosort';
        if ($_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['ordem_cmp'] == $fieldName) {
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['ordem_label'] == 'desc') {
                $sortRule = 'desc';
            } else {
                $sortRule = 'asc';
            }
        }
        return $sortRule;
    }

    function scGetColumnOrderIcon($fieldName, $sortRule, $skipUnusedClass = false)
    {
        $unusedClass = $skipUnusedClass ? '' : ' sc-grid-order-icon-unused';        if ('desc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_desc . "\" />";
        } elseif ('asc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_asc . "\" />";
        } elseif ('' != $this->Ini->Label_sort) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort . "\" />";
        } else {
            return '';
        }
    }

    function scIsFieldNumeric($fieldName)
    {
        switch ($fieldName) {
            case "cdn_fornecedor":
                return true;
            case "val_origin_tit_ap":
                return true;
            case "vl_real":
                return true;
            case "num_id_tit_ap":
                return true;
            case "vl_pagto":
                return true;
            case "num_fatur_ap":
                return true;
            case "val_cm_tit_ap":
                return true;
            case "val_pagto_tit_ap":
                return true;
            case "val_sdo_tit_ap":
                return true;
        }
        return false;
    }

    function scGetDefaultFieldOrder($fieldName)
    {
        switch ($fieldName) {
            case "cdn_fornecedor":
                return 'desc';
            case "dat_emis_docto":
                return 'desc';
            case "dat_vencto_tit_ap":
                return 'desc';
            case "val_origin_tit_ap":
                return 'desc';
            case "num_fatur_ap":
                return 'desc';
            case "dat_transacao":
                return 'desc';
            case "dat_ult_pagto":
                return 'desc';
            case "dat_liquidac_tit_ap":
                return 'desc';
            case "val_cm_tit_ap":
                return 'desc';
            case "val_pagto_tit_ap":
                return 'desc';
            case "val_sdo_tit_ap":
                return 'desc';
        }
        return 'asc';
    }

