   function totaliza_php_sc_free_total()
   {
      $this->sc_proc_grid = true;
      $this->sc_where_orig   = $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['where_orig'];
      $this->sc_where_atual  = $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['where_pesq'];
      $this->sc_where_filtro = $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['where_pesq_filtro'];
      if ($_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['contr_total_geral'] == "OK")
      {
          return;
      }
      //----- 
      if (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_sybase))
      { 
         $nmgp_select = "SELECT cod_estab, cod_espec_docto, cod_ser_docto, cdn_fornecedor, cod_tit_ap, cod_parcela, str_replace (convert(char(10),dat_emis_docto,102), '.', '-') + ' ' + convert(char(8),dat_emis_docto,20), str_replace (convert(char(10),dat_vencto_tit_ap,102), '.', '-') + ' ' + convert(char(8),dat_vencto_tit_ap,20), cod_indic_econ, val_origin_tit_ap, num_id_tit_ap, cod_empresa from " . $this->Ini->nm_tabela; 
      } 
      elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_mssql))
      { 
         $nmgp_select = "SELECT cod_estab, cod_espec_docto, cod_ser_docto, cdn_fornecedor, cod_tit_ap, cod_parcela, convert(char(23),dat_emis_docto,121), convert(char(23),dat_vencto_tit_ap,121), cod_indic_econ, val_origin_tit_ap, num_id_tit_ap, cod_empresa from " . $this->Ini->nm_tabela; 
      } 
      elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_oracle))
      { 
         $nmgp_select = "SELECT cod_estab, cod_espec_docto, cod_ser_docto, cdn_fornecedor, cod_tit_ap, cod_parcela, dat_emis_docto, dat_vencto_tit_ap, cod_indic_econ, val_origin_tit_ap, num_id_tit_ap, cod_empresa from " . $this->Ini->nm_tabela; 
      } 
      elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_informix))
      { 
         $nmgp_select = "SELECT cod_estab, cod_espec_docto, cod_ser_docto, cdn_fornecedor, cod_tit_ap, cod_parcela, EXTEND(dat_emis_docto, YEAR TO DAY), EXTEND(dat_vencto_tit_ap, YEAR TO DAY), cod_indic_econ, val_origin_tit_ap, num_id_tit_ap, cod_empresa from " . $this->Ini->nm_tabela; 
      } 
      else 
      { 
         $nmgp_select = "SELECT cod_estab, cod_espec_docto, cod_ser_docto, cdn_fornecedor, cod_tit_ap, cod_parcela, dat_emis_docto, dat_vencto_tit_ap, cod_indic_econ, val_origin_tit_ap, num_id_tit_ap, cod_empresa from " . $this->Ini->nm_tabela; 
      } 
      $nmgp_select .= " " . $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['where_pesq'] ; 
   $nmgp_order_by = ""; 
   $campos_order_select = "";
   foreach($_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['ordem_select'] as $campo => $ordem) 
   {
        if ($campo != $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['ordem_grid']) 
        {
           if (!empty($campos_order_select)) 
           {
               $campos_order_select .= ", ";
           }
           $campos_order_select .= $campo . " " . $ordem;
        }
   }
   $campos_order = "";
   foreach($_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['ordem_quebra'] as $campo => $resto) 
   {
       foreach($resto as $sqldef => $ordem) 
       {
           $format       = $this->Ini->Get_Gb_date_format($_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['SC_Ind_Groupby'], $campo);
           $campos_order = $this->Ini->Get_date_order_groupby($sqldef, $ordem, $format, $campos_order);
       }
   }
   if (!empty($_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['ordem_grid'])) 
   { 
       if (!empty($campos_order)) 
       { 
           $campos_order .= ", ";
       } 
       $nmgp_order_by = " order by " . $campos_order . $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['ordem_grid'] . $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['ordem_desc']; 
   } 
   elseif (!empty($campos_order_select)) 
   { 
       if (!empty($campos_order)) 
       { 
           $campos_order .= ", ";
       } 
       $nmgp_order_by = " order by " . $campos_order . $campos_order_select; 
   } 
   elseif (!empty($campos_order)) 
   { 
       $nmgp_order_by = " order by " . $campos_order; 
   } 
   if (substr(trim($nmgp_order_by), -1) == ",")
   {
       $nmgp_order_by = " " . substr(trim($nmgp_order_by), 0, -1);
   }
   if (trim($nmgp_order_by) == "order by")
   {
       $nmgp_order_by = "";
   }
   if (empty($nmgp_order_by))
   {
       $nmgp_order_by = " order by cod_estab";
   }
   $nmgp_select .= $nmgp_order_by; 
   $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['order_grid'] = $nmgp_order_by;
      $_SESSION['scriptcase']['sc_sql_ult_comando'] = $nmgp_select; 
      $this->rs_grid = $this->Db->Execute($nmgp_select) ; 
      if ($this->rs_grid === false && !$this->rs_grid->EOF && $GLOBALS["NM_ERRO_IBASE"] != 1) 
      { 
         $this->Erro->mensagem(__FILE__, __LINE__, "banco", $this->Ini->Nm_lang['lang_errm_dber'], $this->Db->ErrorMsg()); 
         exit ; 
      }  
      if ($this->rs_grid->EOF || ($this->rs_grid === false && $GLOBALS["NM_ERRO_IBASE"] == 1)) 
      { 
         $this->nm_grid_sem_reg = "Nenhum título encontrado para o fornecedor do Processo de Compra ou Container. Caso não exista fornecedor informado no  processo de compra ou no container, favor informar o fornecedor."; 
         $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['tot_geral'][1] = 0;
         return;
      }  
      $this->Res->inicializa_arrays();
      $this->nm_grid_colunas = 0;
      while (!$this->rs_grid->EOF) 
      {
         $this->cod_estab = $this->rs_grid->fields[0] ;  
         $this->cod_espec_docto = $this->rs_grid->fields[1] ;  
         $this->cod_ser_docto = $this->rs_grid->fields[2] ;  
         $this->cdn_fornecedor = $this->rs_grid->fields[3] ;  
         $this->cdn_fornecedor = (string)$this->cdn_fornecedor;  
         $this->cod_tit_ap = $this->rs_grid->fields[4] ;  
         $this->cod_parcela = $this->rs_grid->fields[5] ;  
         $this->dat_emis_docto = $this->rs_grid->fields[6] ;  
         $this->dat_vencto_tit_ap = $this->rs_grid->fields[7] ;  
         $this->cod_indic_econ = $this->rs_grid->fields[8] ;  
         $this->rs_grid->fields[9] =  str_replace(",", ".", $this->rs_grid->fields[9]);  
         $this->val_origin_tit_ap = $this->rs_grid->fields[9] ;  
         $this->val_origin_tit_ap = (string)$this->val_origin_tit_ap;  
         $this->num_id_tit_ap = $this->rs_grid->fields[10] ;  
         $this->num_id_tit_ap = (string)$this->num_id_tit_ap;  
         $this->cod_empresa = $this->rs_grid->fields[11] ;  
         $GLOBALS["cdn_fornecedor"] = $this->rs_grid->fields[3] ;  
         $_SESSION['scriptcase']['cons_tit_ap_associar_container_apos_di']['contr_erro'] = 'on';
  $especsAdiant = $this->getEspecsAdiant();
$especsTit    = $this->getEspecsTit();

if(strstr($especsAdiant,$this->cod_espec_docto ) <> false){
	if($this->cod_indic_econ  != 'real'){
   	  $vlReal = $this->buscarVlMoeda($this->num_id_tit_ap ,$this->cod_estab ,	'real');	
	}
	else{
  	  $vlReal = $this->val_origin_tit_ap ;
   }
   $this->vl_real  = $vlReal;	
   $this->vl_pagto  = $this->val_origin_tit_ap ;
}	
if(strstr($especsTit,$this->cod_espec_docto ) <> false){
	$this->inserirLogDb('entrei na opção de titulo','sim',__FUNCTION__);
   $vlDolar = $this->buscarVlMoeda($this->num_id_tit_ap ,$this->cod_estab ,	'dolar');
   $vlReal  = $this->buscarVlMoeda($this->num_id_tit_ap ,$this->cod_estab ,	'real');
   $this->vl_real  = $vlReal;		
	$this->inserirLogDb('codigo indicador econom.',$this->cod_indic_econ ,__FUNCTION__);
	
   if( strtolower($this->cod_indic_econ ) == 'real'){
	$this->inserirLogDb('titulo em real',$vlReal,__FUNCTION__);   
	$this->vl_pagto  = $vlReal;		
   }
   if(strtolower($this->cod_indic_econ ) == 'dolar'){
	$this->inserirLogDb('titulo em dolar',$vlDolar,__FUNCTION__);      
	$this->vl_pagto  = $vlDolar;		
   }		
	
}
$_SESSION['scriptcase']['cons_tit_ap_associar_container_apos_di']['contr_erro'] = 'off';
         $this->GB_cdn_fornecedor = $this->cdn_fornecedor;
         $this->Lookup->lookup_cdn_fornecedor($this->GB_cdn_fornecedor, $this->cdn_fornecedor) ; 
         $this->vl_real = (strpos(strtolower($this->vl_real), "e")) ? (float)$this->vl_real : $this->vl_real; 
         $this->vl_real = (string)$this->vl_real;  
         $this->Res->adiciona_registro(NM_encode_input(sc_strip_script($this->vl_real)));
         $this->rs_grid->MoveNext();
      }
      $this->Res->finaliza_arrays();
      $this->rs_grid->Close();
      $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['tot_geral'][2] = $this->Res->array_total_geral[1];
      $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['contr_array_resumo'] = "OK";
      $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['tot_geral'][0] = "" . $this->Ini->Nm_lang['lang_msgs_totl'] . "";
      $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['tot_geral'][1] = $this->Res->array_total_geral[0];
      $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associar_container_apos_di']['contr_total_geral'] = "OK";
   }

   function nm_conv_data_db($dt_in, $form_in, $form_out)
   {
       $dt_out = $dt_in;
       if (strtoupper($form_in) == "DB_FORMAT") {
           if ($dt_out == "null" || $dt_out == "")
           {
               $dt_out = "";
               return $dt_out;
           }
           $form_in = "AAAA-MM-DD";
       }
       if (strtoupper($form_out) == "DB_FORMAT") {
           if (empty($dt_out))
           {
               $dt_out = "null";
               return $dt_out;
           }
           $form_out = "AAAA-MM-DD";
       }
       if (strtoupper($form_out) == "SC_FORMAT_REGION") {
           $this->nm_data->SetaData($dt_in, strtoupper($form_in));
           $prep_out  = (strpos(strtolower($form_in), "dd") !== false) ? "dd" : "";
           $prep_out .= (strpos(strtolower($form_in), "mm") !== false) ? "mm" : "";
           $prep_out .= (strpos(strtolower($form_in), "aa") !== false) ? "aaaa" : "";
           $prep_out .= (strpos(strtolower($form_in), "yy") !== false) ? "aaaa" : "";
           return $this->nm_data->FormataSaida($this->nm_data->FormatRegion("DT", $prep_out));
       }
       else {
           nm_conv_form_data($dt_out, $form_in, $form_out);
           return $dt_out;
       }
   }
