       $nm_saida->saida("    cloneUl = $('#ul_' + strId).clone( true ).prop('id', 'ul_' + strId + dynamicFilterCount );\r\n");
       $nm_saida->saida("    cloneUl.empty();\r\n");
       $nm_saida->saida("    sub_li = $('<div class=\"group\" />').append(cloneLine).append(cloneUl);\r\n");
