       $nm_saida->saida("             return;\r\n");
       $nm_saida->saida("         }\r\n");
       $nm_saida->saida("         fieldsDisabled = new Array();\r\n");
       $nm_saida->saida("         Cmp_select2_ok = true;\r\n");
       $nm_saida->saida("         for(it=0; it<fieldsDisabled.length; it++)\r\n");
       $nm_saida->saida("         {\r\n");
