       $nm_saida->saida("         htmlNew = htmlNew.replace(/\\__NMSEQ__/g, seq);\r\n");
       $nm_saida->saida("         $( htmlNew ).insertBefore( '#' + $(obj).parent().parent().prop('id') );\r\n");
       $nm_saida->saida("         $('#' + $(obj).parent().parent().prop('id')).remove();\r\n");
