       $nm_saida->saida("function nm_save_grid_search_dyn()\r\n");
       $nm_saida->saida("{\r\n");
       $nm_saida->saida("    if ($(\"#Save_frm_dyn\").hasClass(\"disabled\")) {\r\n");
       $nm_saida->saida("        return;\r\n");
       $nm_saida->saida("    }\r\n");
